{"code":"def transform(grid):
    a=[r[:] for r in grid]
    h=len(a); w=len(a[0])
    # clear all 3s; only right-edge 3 components are translated left
    comps=[]; seen=set()
    for r in range(h):
        for c in range(w):
            if a[r][c]==3 and (r,c) not in seen:
                st=[(r,c)]; seen.add((r,c)); comp=[]
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        q=(x+dx,y+dy)
                        if 0<=q[0]<h and 0<=q[1]<w and q not in seen and grid[q[0]][q[1]]==3:
                            seen.add(q); st.append(q)
                comps.append(comp)
    for r in range(h):
        for c in range(w):
            if a[r][c]==3:a[r][c]=0
    for comp in comps:
        if not any(c==w-1 for r,c in comp): continue
        rows={r:[c for rr,c in comp if rr==r] for r in set(rr for rr,c in comp)}
        for r,cs in rows.items():
            width=len(cs); left=min(cs); x=left-1
            while x>=0 and grid[r][x]==0: x-=1
            newleft=x+1
            for c in range(newleft,newleft+width): a[r][c]=3
    return a"}

